import { useCallback, useRef } from 'react'
import { createPortal } from 'react-dom'
import { Button } from '../../../../../components'
import BottomActionSheet from '../../../../../components/BottomActionSheet'
import DynamicForm from '../../../../../components/DynamicForm'
import Heading from '../../../../../components/Heading'
import { LANG_STRINGS } from '../../../../../lang'
import { ChangeEmailStyle } from './index.style'

function ChangeCustomerEmail ({ show, onClose, oldEmail, onChangeEmail = () => {} }) {
  const parentRef = useRef()

  const handleSend = useCallback((e) => {
    const data = parentRef.current.validateFormValues(e)
    if (data?.new_email) {
      onChangeEmail(data?.new_email)
    }
  }, [onChangeEmail])

  return show ? createPortal(
    <BottomActionSheet
      show={show}
      onCloseSheet={onClose}
    >
      <ChangeEmailStyle>
        <Heading
          title={LANG_STRINGS.changeEmailAddress}
        />
        <DynamicForm
          form={[
            {
              type: 'email',
              title: LANG_STRINGS.previousEmailAddress,
              defaultValue: oldEmail,
              name: 'email',
              disabled: true
            },
            {
              type: 'email',
              title: LANG_STRINGS.newEmailAddress,
              placeholder: 'Alamat Email',
              name: 'new_email',
              required: true
            }
          ]}
          ref={parentRef}
          formName='emailChange'
        />
        <Button onClick={handleSend}>
          {LANG_STRINGS.sendPaymentLink}
        </Button>
      </ChangeEmailStyle>
    </BottomActionSheet>,
    document.getElementById('bottom-sheet-portal')
  ) : null
}

export default ChangeCustomerEmail
