import { forwardRef, useCallback, useImperativeHandle, useRef, useState, useEffect } from 'react'
import { typeValid } from '../../helpers/validations'
import AutoSearchBottomSheet from './components/AutoSearchBottomSheet'
import AutoSearchBottomSheetV2 from './components/AutoSearchBottomSheetV2'
import AutoSearchBottomSheetVehicleBrands from './components/AutoSearchBottomSheetVehicleBrands'
import AutoSearchBottomSheetVehicleModels from './components/AutoSearchBottomSheetVehicleModels'
import DatePicker from './components/DatePicker'
import Input from './components/Input'
import InputNumber from './components/InputNumber'
import InputV2 from './components/InputV2'
import RadioInput from './components/RadioInput'
import { LANG_STRINGS, ERROR_LANG } from '../../lang/index'
import UploadFile from './components/UploadFile'
import RadioWithIconBox from './components/RadioWithIconBox'
import RadioV2 from './components/RadioV2'
import Address from './Address'
import TimePicker from './components/TimePicker'
import DateTimePicker from './components/DateTimerPicker'
import { size } from 'lodash'
import MultipleSelect from './components/MultipleSelect'
import DatePickerV3 from './components/DatePickerV3'
import InputNumberV2 from './components/InputNumberV2'
import { Grid } from '../../commonStyle/index.style'
import UploadFileV3 from './components/UploadFileV3'
import NumberStepper from './components/NumberStepper'
import ActionBox from './components/ActionBox'
import InformationBox from './components/InformationBox'
import Checkbox from './components/Checkbox'
import InputPhoneNumber from './components/InputPhoneNumber'
import PopupApi from './components/PopupApi'
import PopupApiPinned from './components/PopupApiPinned'

function DynamicForm(
  {
    form,
    formName = 'dynamicForm',
    onChange = () => {},
    isValidateOnChange = false,
    isDocSlider,
    className = '',
    style = {},
  },
  parentRef
) {
  const that = useRef({})
  const autoSearchInputRef = useRef({})
  const addressRef = useRef({})
  const [errorMap, setErrorMap] = useState({})

  useEffect(() => {
    // doing because of docSlider focus in effect attaching all inputs
    if (isDocSlider) {
      const el = document.getElementById(formName)
      el.addEventListener('focusin', (e) => {
        e.preventDefault()
        e.stopPropagation()
      })
    }
  }, [isDocSlider, formName])

  const getErrorValue = useCallback((type) => {
    switch (type) {
      case 'multiple_select':
        return 'Pilih minimal 1 item'
      case 'checkbox':
      case 'select':
        return 'Harus Dipilih'
      case 'number':
        return 'Harus Angka'
      case 'chasis_number':
      case 'machine_number':
        return 'Format Tidak Valid'
      case 'phone_number':
        return ERROR_LANG.phoneRequiredError
      case 'email':
      case 'emailV2':
        return 'Format email tidak sesuai'
      default:
        return 'Harus Diisi'
    }
  }, [])

  const validateFieldValue = useCallback(
    (field, value) => {
      const {
        type,
        validationType,
        name,
        data,
        required,
        validation,
        regex_validation: regexValidation,
        error,
        errormsg,
      } = field

      // Use validationType if provided, otherwise use type
      const validationTypeToUse = validationType || type

      if (type === 'inputGrid') {
        const gridErrors = []
        for (let i = 0; i < field.gridColumn; i++) {
          if (required && !value[i]) {
            gridErrors[i] = LANG_STRINGS.required
          } else if (value[i] && regexValidation?.[i] && !regexValidation[i].test(value[i])) {
            gridErrors[i] = errormsg?.[i] || LANG_STRINGS.invalidInput
          }
        }
        return { isError: gridErrors.length > 0, error: gridErrors }
      } else if (required && !value) {
        return { isError: true, error: LANG_STRINGS.required }
      } else if (value && regexValidation) {
        const regex =
          regexValidation instanceof RegExp ? regexValidation : new RegExp(regexValidation)
        if (!regex.test(value)) {
          return { isError: true, error: errormsg }
        }
      } else if (
        required &&
        type !== 'address' &&
        (!typeValid(validationTypeToUse, value) || (data?.isMultiple && !size(value)))
      ) {
        return {
          isError: true,
          error: value ? error || getErrorValue(validationTypeToUse) : LANG_STRINGS.required,
        }
      } else if (type === 'address') {
        const address = addressRef.current[name] && addressRef.current[name].validateAddressForm()
        if (!address) {
          return { isError: true, error: LANG_STRINGS.required }
        }
      } else if (required && value && validation) {
        if (
          (typeof validation === 'function' && validation(value)) ||
          (typeof validation !== 'function' && validation !== value)
        ) {
          return { isError: true, error: error }
        }
      }
      return { isError: false, error: null }
    },
    [getErrorValue]
  )

  useImperativeHandle(parentRef, () => ({
    validateFormValues: (isShowError = true) => {
      const visibleFieldNames = new Set(form.map((f) => f.name))
      const errorObj = {}
      Object.entries(errorMap).forEach(([name, err]) => {
        if (!visibleFieldNames.has(name)) return
        if (that.current[name]) return
        errorObj[name] = err
      })

      form.forEach((field) => {
        const { isError, error } = validateFieldValue(field, that.current[field.name])
        if (isError) errorObj[field.name] = error
      })
      if (isShowError) setErrorMap(errorObj)
      if (Object.keys(errorObj).length) {
        return null
      }
      return that.current
    },
    resetAutoSearch: (resetKeyName) => {
      autoSearchInputRef.current[resetKeyName].resetSearch(resetKeyName)
    },
    resetFormField: (name, value) => {
      that.current[name] = value
    },
    setErrorMap: (error) => {
      setErrorMap((oldError) => ({
        ...oldError,
        ...error,
      }))
    },
  }))

  const handleChange = useCallback(
    (item, additional) => {
      that.current = {
        ...that.current,
        [item.name]: item.value,
      }

      if (errorMap[item.name]) {
        setErrorMap((oldErrorMap) => {
          delete oldErrorMap[item.name]
          return { ...oldErrorMap }
        })
      }

      if (isValidateOnChange) {
        const field = form.find((f) => f.name === item.name)
        const { isError, error } = validateFieldValue(field, item.value)
        if (isError) {
          setErrorMap((oldErrorMap) => ({ ...oldErrorMap, [item.name]: error }))
        }
      }

      if (item.type === 'inputGrid') {
        const changedValue = Object.fromEntries(
          item.name.map((name, index) => [name, item.value[index]])
        )
        onChange({ ...changedValue, ...additional })
      } else {
        onChange({ [item.name]: item.value, ...additional })
      }
    },
    [onChange, form, errorMap, isValidateOnChange, validateFieldValue]
  )

  const renderInputElements = useCallback(
    (props) => {
      const {
        type,
        name,
        title,
        data,
        required,
        defaultValue,
        disabled,
        hidden,
        hiddenIcon,
        designV2,
      } = props
      if (hidden) return null

      // data may contains the object or array that need for the input element
      // render each element
      if (defaultValue && !Object.hasOwnProperty.call(that.current, name)) {
        // store default only if key not exist
        that.current[name] = defaultValue
      }

      const isMobileNo = type === 'inputNumberV2' && name === 'mobile_no'

      switch (type) {
        case 'multiple_select':
          return (
            <MultipleSelect
              key={`form_${name}`}
              {...data}
              title={title}
              name={name}
              required={required}
              defaultValue={defaultValue}
              onChange={handleChange}
              error={errorMap[name]}
            />
          )
        case 'radio':
          return (
            <RadioInput
              key={`form_${name}`}
              data={data}
              title={title}
              name={name}
              required={required}
              defaultSelected={defaultValue}
              onChange={handleChange}
              error={errorMap[name]}
            />
          )
        case 'datePicker':
          return (
            <DatePicker
              key={`form_${name}`}
              {...data}
              title={title}
              name={name}
              required={required}
              defaultValue={defaultValue}
              onChange={handleChange}
              error={errorMap[name]}
            />
          )
        case 'timePicker':
          return (
            <TimePicker
              key={`form_${name}`}
              {...data}
              title={title}
              name={name}
              required={required}
              defaultValue={defaultValue}
              onChange={handleChange}
              error={errorMap[name]}
            />
          )
        case 'dateTimerPicker':
          return (
            <DateTimePicker
              key={`form_${name}`}
              {...data}
              title={title}
              name={name}
              required={required}
              defaultValue={defaultValue}
              onChange={handleChange}
              error={errorMap[name]}
            />
          )
        case 'datePickerV3':
          return (
            <DatePickerV3
              key={`form_${name}`}
              {...data}
              label={title}
              name={name}
              error={errorMap[name]}
              defaultValue={defaultValue}
              selectionType="single"
              maxDate={data?.maxDate || ''}
              minDate={data?.minDate || ''}
              onChange={handleChange}
              disabled={disabled}
            />
          )
        case 'autoSearchBottomSheet':
          return (
            <AutoSearchBottomSheet
              key={`form_${name}`}
              {...data}
              title={title}
              name={name}
              required={required}
              defaultValue={defaultValue}
              onChange={(value) => handleChange({ value, name })}
              error={errorMap[name]}
              ref={(instance) => {
                autoSearchInputRef.current[name] = instance
              }}
              designV2
            />
          )
        case 'autoSearchBottomSheetv2':
          return (
            <AutoSearchBottomSheetV2
              key={`form_${name}`}
              margin
              {...data}
              title={title}
              name={name}
              required={required}
              defaultValue={defaultValue}
              disabled={disabled}
              onChange={(value) => handleChange({ value, name })}
              error={errorMap[name]}
              ref={(instance) => {
                autoSearchInputRef.current[name] = instance
              }}
            />
          )
        case 'autoSearchBottomSheetVehicleBrands':
          return (
            <AutoSearchBottomSheetVehicleBrands
              key={`form_${name}`}
              margin
              {...data}
              title={title}
              name={name}
              required={required}
              defaultValue={defaultValue}
              disabled={disabled}
              onChange={(value) => handleChange({ value, name })}
              error={errorMap[name]}
              ref={(instance) => {
                autoSearchInputRef.current[name] = instance
              }}
            />
          )
        case 'autoSearchBottomSheetVehicleModels':
          return (
            <AutoSearchBottomSheetVehicleModels
              key={`form_${name}`}
              margin
              {...data}
              title={title}
              name={name}
              required={required}
              defaultValue={defaultValue}
              disabled={disabled}
              onChange={(value) => handleChange({ value, name })}
              error={errorMap[name]}
              ref={(instance) => {
                autoSearchInputRef.current[name] = instance
              }}
            />
          )
        case 'chasis_number':
          return (
            <Input
              key={`form_${name}`}
              {...data}
              title={title}
              name={name}
              required={required}
              defaultValue={defaultValue}
              error={errorMap[name]}
              onChange={(e) => handleChange({ value: e.target.value, name: name })}
            />
          )
        case 'address':
          return (
            <Address
              key={`form_${name}`}
              name={name}
              {...data}
              defaultValue={defaultValue}
              required={required}
              designV2={designV2}
              error={errorMap[name]}
              onChange={(data) => handleChange({ value: data, name })}
              ref={(instance) => {
                addressRef.current[name] = instance
              }}
            />
          )
        case 'text':
        case 'email':
        case 'name':
        case 'color':
        case 'machine_number':
        case 'textarea':
          return (
            <Input
              key={`form_${name}`}
              {...data}
              title={title}
              name={name}
              required={required}
              defaultValue={defaultValue}
              disabled={disabled}
              error={errorMap[name]}
              type={type}
              onChange={(e) => handleChange({ value: e.target.value, name: name })}
            />
          )
        case 'phone_number':
        case 'amount':
        case 'number':
        case 'ktp':
        case 'postal_code':
          return (
            <InputNumber
              key={`form_${name}`}
              {...data}
              title={title}
              name={name}
              required={required}
              defaultValue={defaultValue}
              disabled={disabled}
              error={errorMap[name]}
              onChange={(e) => handleChange({ value: e.target.value, name: name })}
            />
          )
        case 'npwp':
          return (
            <InputNumber
              key={`form_${name}`}
              {...data}
              title={title}
              name={name}
              required={required}
              defaultValue={defaultValue}
              disabled={disabled}
              error={errorMap[name]}
              onChange={(item) => handleChange({ value: item, name: name })}
            />
          )
        case 'number-hidden':
          return (
            <InputNumber
              key={`form_${name}`}
              {...data}
              title={title}
              name={name}
              type="hidden"
              required={required}
              defaultValue={defaultValue}
              disabled={disabled}
              hiddenIcon={hiddenIcon}
              error={errorMap[name]}
              onChange={(e) => handleChange({ value: e.target.value, name: name })}
            />
          )
        case 'uploadFile':
          return (
            <UploadFile
              key={`form_${name}_${type}`}
              {...data}
              name={name}
              title={title}
              required={required}
              disabled={disabled}
              defaultValue={defaultValue}
              error={errorMap[name]}
              onChange={(value) => handleChange({ value, name: name })}
            />
          )
        case 'uploadFileV3':
          return (
            <UploadFileV3
              key={`form_${name}_${type}`}
              {...data}
              name={name}
              title={title}
              required={required}
              disabled={disabled}
              defaultValue={defaultValue}
              error={errorMap[name]}
              onChange={(value) => handleChange({ value, name: name })}
            />
          )
        case 'radioWithIcon':
          return (
            <RadioWithIconBox
              key={`form_${name}_${type}`}
              data={data}
              name={name}
              title={title}
              required={required}
              defaultValue={defaultValue}
              error={errorMap[name]}
              onChange={(value) => handleChange(value)}
            />
          )
        case 'radioV2':
          return (
            <RadioV2
              key={`form_${name}_${type}`}
              {...data}
              name={name}
              title={title}
              required={required}
              defaultValue={defaultValue}
              disabled={disabled}
              error={errorMap[name]}
              onChange={handleChange}
            />
          )
        case 'numberStepper':
          return (
            <NumberStepper
              key={`form_${name}_${type}`}
              {...data}
              defaultValue={defaultValue}
              disabled={disabled}
              onChange={(value) => handleChange({ name, value })}
            />
          )
        case 'actionBox':
          return <ActionBox key={`form_${name}_${type}`} {...data} onChange={handleChange} />
        case 'popupApi':
          return (
            <PopupApi
              key={`form_${name}_${type}`}
              {...data}
              title={title}
              name={name}
              required={required}
              defaultValue={defaultValue}
              disabled={disabled}
              error={errorMap[name]}
              onChange={handleChange}
            />
          )
        case 'popupApiPinned':
          return (
            <PopupApiPinned
              key={`form_${name}_${type}`}
              {...data}
              title={title}
              name={name}
              required={required}
              defaultValue={defaultValue}
              disabled={disabled}
              error={errorMap[name]}
              onChange={handleChange}
            />
          )
        case 'informationBox':
          return <InformationBox key={`form_${name}_${type}`} {...data} />
        case 'checkbox':
          return (
            <Checkbox
              key={`form_${name}_${type}`}
              name={name}
              title={title}
              required={required}
              disabled={disabled}
              defaultValue={defaultValue}
              description={data?.description}
              error={errorMap[name]}
              onChange={(value) => handleChange(value)}
            />
          )
        case 'inputPhoneNumber':
          return (
            <InputPhoneNumber
              key={`form_${name}`}
              name={name}
              placeholder={title}
              defaultValue={defaultValue}
              required={required}
              disabled={disabled}
              error={errorMap[name]}
              onChange={({ value }) => handleChange({ name, value })}
              bottom="1rem"
            />
          )
        case 'inputV2':
        case 'emailV2':
          return (
            <InputV2
              key={`form_${name}`}
              {...data}
              title={title}
              name={name}
              required={required}
              defaultValue={defaultValue}
              disabled={disabled}
              error={errorMap[name]}
              type={type}
              onChange={(e) => handleChange({ value: e.target.value, name: name })}
              bottom="1rem"
            />
          )
        case 'inputNumberV2':
          return (
            <InputNumberV2
              key={`form_${name}`}
              placeholder={title}
              {...data}
              value={
                isMobileNo
                  ? that.current[name]
                    ? that.current[name].replace(/^\+62/, '')
                    : ''
                  : that.current[name] || ''
              }
              onChange={(e) => {
                if (isMobileNo) {
                  handleChange({
                    value: '+62' + e.value.replace(/[^\d]/g, ''),
                    name,
                  })
                } else {
                  handleChange({ value: e.value, name })
                }
              }}
              error={errorMap[name]}
              bottom="1rem"
              {...(isMobileNo ? { prefix: '+62' } : {})}
            />
          )
        case 'inputGrid': {
          const gridColumn = Array(props.gridColumn).fill('1fr').join(' ')
          return (
            <Grid
              key={`form_${name?.join('_')}`}
              gridColumn={gridColumn}
              gridGap="1rem"
              width="100%"
              style={{ minWidth: 0 }}
            >
              {props.gridType.map((gridType, idx) => {
                switch (gridType) {
                  case 'inputNumberV2':
                    return (
                      <div key={`form_${name[idx]}`} style={{ minWidth: 0 }}>
                        <InputNumberV2
                          name={name[idx]}
                          title={title[idx]}
                          placeholder={title[idx]}
                          required={required[idx]}
                          disabled={disabled[idx]}
                          value={defaultValue[idx] || ''}
                          onChange={(e) => {
                            const newValue = [...that.current[name]]
                            newValue[idx] = e.value
                            handleChange({ type, value: newValue, name: name })
                          }}
                          error={errorMap[name]?.[idx]}
                          {...data[idx]}
                        />
                      </div>
                    )
                  case 'inputV2':
                  default:
                    return (
                      <div key={`form_${name[idx]}`} style={{ minWidth: 0 }}>
                        <InputV2
                          name={name[idx]}
                          title={title[idx]}
                          placeholder={title[idx]}
                          required={required[idx]}
                          disabled={disabled[idx]}
                          defaultValue={defaultValue[idx]}
                          onChange={(e) => {
                            const newValue = [...that.current[name]]
                            newValue[idx] = e.target.value
                            handleChange({ type, value: newValue, name: name })
                          }}
                          error={errorMap[name]?.[idx]}
                          {...data[idx]}
                        />
                      </div>
                    )
                }
              })}
            </Grid>
          )
        }
        default:
          return null
      }
    },
    [handleChange, errorMap]
  )

  return (
    <div id={formName} className={className} style={style}>
      {form.map((formItem) => renderInputElements(formItem))}
    </div>
  )
}

export default forwardRef(DynamicForm)
