import { useCallback, useEffect, useMemo, useRef } from 'react'
import { connect } from 'react-redux'
import { DisplayFlexCCC, Row } from '../../../../commonStyle/index.style'
import { Button, Container, CustomText } from '../../../../components'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import { SEND_QUOTATION_SUCCESS } from '../../../../constants/cookies'
import { removeFromLocalStorageData } from '../../../../helpers/localstorage'
import { INFORMATION_SENT, PAYMENT_PENDING_IMG } from '../../../../images/imageUrl'
import { LANG_STRINGS } from '../../../../lang'
import { SendQuotationSuccessStyle } from './index.style'
import actions from '../../../../redux/auth/action'
import { useHistory } from 'react-router-dom'
import { useParams } from 'react-router'
import QuoteActions from '../components/QuoteActions'
import { useGetDraftQuoteDetails, useGetPolicyDetails } from '../../Policy/state/hooks/usePolicyState'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'

const { logoutGuardian } = actions

function SendQuotationSuccessContainer ({ ...props }) {
  const history = useHistory()
  const { quoteId, type, draftQuoteId } = useParams()
  const that = useRef({
    isAgentPaid: type === 'agent-paid',
    isPaymentSuccess: type === 'link_success',
    isPayLater: type === 'paylater'
  })
  const [{
    GET_DOWNLOAD_DRAFT_PDF_LOADER, GET_POLICY_DETAIL_LOADER,
    RESEND_PAYMENT_LINK_LOADER, UPDATE_EMAIL_LOADER,
    DRAFT_QUOTATIONS_DETAILS_LOADER, GET_DOWNLOAD_PDF_LOADER
  }] = useLoaderContextValue()
  const [{ getPolicyDetailData = {} }, getPolicyDetailRequest] = useGetPolicyDetails()
  const [{ draftQuotationsDetailsData = {} }, getDraftQuoteDetailsReq] = useGetDraftQuoteDetails()

  const pageData = useMemo(() => {
    let title = LANG_STRINGS.thankYou
    let subTitle = LANG_STRINGS.youOfferHasBeenSent
    let icon = INFORMATION_SENT
    const email = getPolicyDetailData.customer_data && getPolicyDetailData.customer_data.email
    if (that.current.isPaymentSuccess) {
      title = LANG_STRINGS.paymentLinkSentNew
      subTitle = `${LANG_STRINGS.paymentLinkSentEmail} <b>${email}</b> ${LANG_STRINGS.paymentActiveTimeStatement}`
    } else if (that.current.isPayLater) {
      title = LANG_STRINGS.waitingVerification
      icon = PAYMENT_PENDING_IMG
      subTitle = LANG_STRINGS.waitingPaymentMethod
    } else if (that.current.isAgentPaid) {
      subTitle = LANG_STRINGS.yourPaymentGetProcessed
    }
    return {
      title,
      subTitle,
      email,
      icon
    }
  }, [getPolicyDetailData])

  const quote = useMemo(() => {
    if (quoteId) return getPolicyDetailData

    if (draftQuoteId && draftQuotationsDetailsData?.policy_details) {
      const policyDetails = draftQuotationsDetailsData?.policy_details
      const totalBill = policyDetails?.total_bill || policyDetails?.package_data?.total_bill
      return {
        ...draftQuotationsDetailsData,
        ...policyDetails?.package_data,
        policy_detail: {
          ...policyDetails
        },
        product: {
          ...policyDetails.package_data
        },
        premium: {
          period: 12,
          amount: policyDetails?.package_data?.basic_premium
        },
        customer_data: policyDetails.customer_data,
        total_premium: totalBill,
        draft_id: draftQuoteId,
        total_bill: totalBill
      }
    }
  }, [quoteId, getPolicyDetailData, draftQuotationsDetailsData, draftQuoteId])

  useEffect(() => {
    const handler = () => {
      history.push('/dashboard')
      window.removeEventListener('popstate', handler)
    }

    window.addEventListener('popstate', handler)
  }, [history])

  useEffect(() => {
    if (quoteId) {
      getPolicyDetailRequest({
        policyId: quoteId
      })
    } else if (draftQuoteId) {
      getDraftQuoteDetailsReq({
        draftQuoteId
      })
    }
  }, [quoteId, draftQuoteId, getDraftQuoteDetailsReq, getPolicyDetailRequest])

  useEffect(() => {
    removeFromLocalStorageData(SEND_QUOTATION_SUCCESS)
  }, [])

  const handleGetPolicyDetails = useCallback(() => {
    getPolicyDetailRequest({
      policyId: quoteId
    })
  }, [quoteId, getPolicyDetailRequest])

  const handleToTransaction = useCallback(() => {
    let path = `/transactions/${quoteId}/details`
    history.replace(path)
  }, [history, quoteId])

  const handleLogoutGuardianAgent = () => {
    props.logoutGuardian(true)
  }

  if (props.isGuardianAgentLogin) {
    return (
      <Container
        title={LANG_STRINGS.sendOffer}
        displayBackButton
        className='bg-white'
        hideGuardianInfo
        loader={GET_DOWNLOAD_PDF_LOADER || GET_POLICY_DETAIL_LOADER}
      >
        <SendQuotationSuccessStyle>
          <DisplayFlexCCC>
            <img src={INFORMATION_SENT} alt='' />
            <CustomText
              color={AgentColorPallette.black}
              size='20px'
              top='25px'
              bottom='25px'
              textAlign='center'
              weight={800}
            >
              {LANG_STRINGS.offersHasBeenSent}
            </CustomText>
            <CustomText
              color={AgentColorPallette.black}
              bottom='25px'
              size='14px'
              textAlign='center'
            >
              Silahkan keluar dari akun&nbsp;
              <span className='golden-text'>{`"${props.agentDetails.name}"`}</span>&nbsp;
              untuk menghindari kesalahan pengiriman penawaran lainnya dari akun&nbsp;
              <span className='golden-text'>{`"${props.agentDetails.name}"`}</span>
            </CustomText>
            <Row justify='space-between' width='100%'>
              <Button onClick={handleLogoutGuardianAgent}>
                {LANG_STRINGS.exit}
              </Button>
            </Row>
          </DisplayFlexCCC>
        </SendQuotationSuccessStyle>
      </Container>
    )
  } else {
    return (
      <Container
        title={LANG_STRINGS.sendOffer}
        displayBackButton
        className='bg-white'
        hideBottomTabs
        hideHeader
        hideGuardianInfo
        loader={
          GET_DOWNLOAD_PDF_LOADER || GET_POLICY_DETAIL_LOADER || RESEND_PAYMENT_LINK_LOADER ||
          UPDATE_EMAIL_LOADER || DRAFT_QUOTATIONS_DETAILS_LOADER || GET_DOWNLOAD_DRAFT_PDF_LOADER
        }
      >
        <SendQuotationSuccessStyle>
          <img
            className='quotation-img'
            src={pageData.icon}
            alt=''
            width='180px'
          />
          <CustomText
            color={AgentColorPallette.blackGrey}
            size='1.4em'
            top='1rem'
            bottom='0.4rem'
            textAlign='center'
            weight={800}
          >
            {pageData.title}
          </CustomText>
          <CustomText
            color={AgentColorPallette.black}
            size='14px'
            textAlign='center'
            bottom='1rem'
            dangerouslySetInnerHTML={{
              __html: pageData.subTitle
            }}
          />
          <Button
            onClick={handleToTransaction}
            color={AgentColorPallette.blackGrey}
            data-gtm-element-id='transactions-draft-details'
            data-gtm-entry='quote-shared-with-customer'
          >
            {LANG_STRINGS.viewYourOrder}
          </Button>
          <QuoteActions
            quote={quote}
            email={pageData.email}
            isDraft={!!draftQuoteId}
            onUpdateEmailChange={handleGetPolicyDetails}
            isPaymentSuccess={that.current.isPaymentSuccess}
            isPayLater={that.current.isPayLater}
          />
        </SendQuotationSuccessStyle>
      </Container>
    )
  }
}

export default connect(
  state => ({
    agentDetails: state.User.agentDetails,
    isGuardianAgentLogin: state.Auth.isGuardianAgentLogin
  }),
  {
    logoutGuardian
  }
)(SendQuotationSuccessContainer)
