import { DisplayFlexCCC, Grid } from '../../../../commonStyle/index.style'
import { ARROW_SELECTION, CALL_HELP, CLOSE_GREY, ITEM_NOT_FOUND, SEARCH } from '../../../../images'
import { AutoSearchStyleSheet, SearchListStyle, Label, SelectDrop, SelectInput, SelectContainer } from './index.style'
import { LANG_STRINGS } from '../../../../lang/index'
import BottomActionSheet from '../../../BottomActionSheet'
import { useState, useCallback, useMemo, useRef, forwardRef, useEffect, useImperativeHandle } from 'react'
import debounce from 'lodash/debounce'
import { CustomText } from '../../..'
import { AgentColorPallette } from '../../../../configs/colorPallete'
import Heading from '../../../Heading/index'
import { useShowAgentPIC } from '../../../../state/globalState/hooks/useGlobalContext'
import { createPortal } from 'react-dom'

function AutoSearchBottomSheetVehicleModels ({
  title, required, data, name, displayKey, dataKey,
  children, onRenderList, defaultValue = {}, error, isHideField,
  isIconWithBox, onChange = () => {}, onCloseSheet, showHeader = false, headerTitle, disabled = false, margin
}, parentRef) {
  const [show, setShow] = useState(false || isHideField)
  const [query, setQuery] = useState('')
  const [selected, setSelected] = useState(defaultValue && defaultValue[dataKey])
  const [displayValue, setDisplayValue] = useState(defaultValue && defaultValue[displayKey])
  const [openAccordions, setOpenAccordions] = useState({})
  const list = useMemo(() => {
    if (!data) return {}
  
    return Object.fromEntries(
      Object.keys(data).sort((a, b) => a.localeCompare(b)).map((modelName) => {
        const filteredVariants = data[modelName].filter((variant) =>
          variant[displayKey].toLowerCase().includes(query.toLowerCase())
        )
        return [modelName, filteredVariants]
      }).filter(([, variants]) => variants.length > 0)
    )
  }, [data, displayKey, query])
  const that = useRef({ isEvent: false })
  const inputRef = useRef()
  const [, handleShowPicInfo] = useShowAgentPIC()

  useImperativeHandle(parentRef, () => ({
    resetSearch: (resetKeyName) => {
      if (resetKeyName === name) {
        setSelected('')
        setDisplayValue('')
        onChange(null)
      }
    }
  }))

  useEffect(() => {
    if (!that.current.isEvent) {
      that.current.isEvent = true
      const el = document.getElementById('search-header')
      if (el) {
        el.addEventListener('focusin', (e) => {
          e.preventDefault()
          e.stopPropagation()
        })
      }
    }
  }, [])

  useEffect(() => {
    if (!selected && defaultValue) {
      setSelected(defaultValue[dataKey])
      setDisplayValue(defaultValue[displayKey])
    }
  }, [defaultValue, selected, displayKey, dataKey])

  const handleCloseSheet = useCallback(() => {
    if (isHideField && onCloseSheet) {
      onCloseSheet()
    }
    setShow(false)
    setQuery('')
    setOpenAccordions({})
    inputRef.current.value = ''
  }, [onCloseSheet, isHideField])

  const handleSelected = useCallback((item) => {
    // set selected item
    setSelected(item[dataKey])
    setDisplayValue(item[displayKey])
    setShow(false)
    setQuery('')
    inputRef.current.value = ''
    onChange(item)
  }, [dataKey, displayKey, onChange])

  const handleShowQuickHelp = useCallback(() => {
    handleShowPicInfo()
  }, [handleShowPicInfo])

  const toggleAccordion = (modelName) => {
    setOpenAccordions((prev) => ({
      ...prev,
      [modelName]: !prev[modelName],
    }))
  }

  const renderNotFoundItem = useCallback(() => {
    // return not found result
    return (
      <div className='other-option'>
        <DisplayFlexCCC className='not-found-box'>
          <div>
            <img width='180px' src={ITEM_NOT_FOUND} alt='Not Found' />
          </div>
          <div>
            <CustomText
              color={AgentColorPallette.blackGrey}
              weight={700}
              size='1.5em'
              bottom='8px'
              textAlign='center'
            >
              {LANG_STRINGS.oops}
            </CustomText>
            <CustomText
              color={AgentColorPallette.blackGrey}
              size='0.9em'
              textAlign='center'
              bottom='1rem'
            >
              {LANG_STRINGS.weCouldNotFoundItem}
            </CustomText>
          </div>
        </DisplayFlexCCC>
        <Heading
          title={LANG_STRINGS.moreOptions}
          className='heading-width'
        />
        <button className='contact-us' onClick={handleShowQuickHelp}>
          <div>
            <img src={CALL_HELP} alt='Call Help' />
          </div>
          {LANG_STRINGS.contactUs}
        </button>
      </div>
    )
  }, [handleShowQuickHelp])

  const renderSearchItemContainer = useCallback(() => {
    if (!data) {
      return renderNotFoundItem()
    }
    // if (onRenderList) {
    //   return onRenderList(list)
    // }

    {
      return (
        Object.keys(list).map((modelName) => (
          <div key={modelName} className=''>
            <div
              className='accordion-header'
              onClick={() => toggleAccordion(modelName)}
            >
              {modelName}
              <i
                className={`fas fa-caret-down ${openAccordions[modelName] ? 'fa-angle-up caret-rotate-up' : 'fa-angle-down caret-rotate-down'}`}
              />
            </div>
            {openAccordions[modelName] && (
              <div className=''>
                {list[modelName].map((variant) => (
                  <div
                    className={`search-list-item variant-text ${(selected === variant[dataKey]) && 'selected-active'}`}
                    key={variant[dataKey]}
                    onClick={() => handleSelected(variant)}
                  >
                    {variant[displayKey]}
                  </div>
                ))}
              </div>
            )}
          </div>
        ))
      )
    }
  }, [
    displayKey, dataKey, selected,
    isIconWithBox, handleSelected, renderNotFoundItem,
    onRenderList
  ])

  const handleOnChange = debounce(useCallback((e) => {
    setQuery(e.target.value)
  }, []), 350)

  return (
    <AutoSearchStyleSheet error={error}>
      {!isHideField && (
        <>
          {
            <SelectContainer className={margin ? 'auto-input-box' : ''}>
              <Label active={show || displayValue}>
                {title}
              </Label>
              <SelectDrop disabled={disabled} onClick={(e) => {
                e.stopPropagation();
                setShow(true);
              }}>
                <SelectInput
                  value={displayValue}
                  isOptionContainerOpen={show}
                  readOnly
                  // onChange={selectInputChangeHandler}
                />
                <img src={ARROW_SELECTION} alt="Select" />
              </SelectDrop>
            </SelectContainer>
          }
        </>)}
      {
        show && createPortal(
          <BottomActionSheet
            show={show}
            onCloseSheet={handleCloseSheet}
            zIndex={5}
            showHeader={showHeader}
            title={headerTitle}
            backGroundColor
          >
            <SearchListStyle>
              <Grid
                gridColumn='24px 1fr 34px'
                gridGap='0.9rem'
                className='search-header'
                id='search-header'
              >
                <div className='search-icon'>
                  <img src={SEARCH} alt='Search' />
                </div>
                <input
                  className='search-input'
                  placeholder={`${LANG_STRINGS.search}...`}
                  onChange={handleOnChange}
                  ref={inputRef}
                />
                {
                  !showHeader &&
                    <div className='search-close-icon' onClick={handleCloseSheet}>
                      <img src={CLOSE_GREY} alt='close' />
                    </div>
                }
              </Grid>
              <div
                className='search-container-list'
              >
                {renderSearchItemContainer()}
              </div>
            </SearchListStyle>
          </BottomActionSheet>,
          document.getElementById('bottom-sheet-portal')
        )
      }
    </AutoSearchStyleSheet>
  )
}

export default forwardRef(AutoSearchBottomSheetVehicleModels)
