import { QUOTE_SUCCESS_ACTIONS, CUSTOMER_PAYMENT_SUCCESS_ACTIONS } from '../../constants'
import { QuoteActionsStyle } from './index.style'
import { useCallback, useMemo, useState, useEffect } from 'react'
import Heading from '../../../../../components/Heading'
import { LANG_STRINGS } from '../../../../../lang/index'
import { getFromLocalStorageData } from '../../../../../helpers/localstorage'
import { SEND_QUOTATION_SUCCESS } from '../../../../../constants/cookies'
import { HEALTH_FULL_PROTECTION, PROPERTY_PROTECTION_BASIC, MARINE_CARGO_PROTECTION, CAR_PROTECTION } from '../../../../../constants/pkgCode'
import { APP_HOST } from '../../../../../configs/url'
import { copySharingData, formatMoney, queryBuilder } from '../../../../../helpers/utility'
import { gTagOnSendSendQuotationWA } from '../../../../../tagManager'
import { ANDROID_BRIDGE } from '../../../../../bridges/android'
import { WHATS_APP_URL } from '../../../../../constants/appUrls'
import { useHistory } from 'react-router-dom'
import ShowSnackbar from '../../../../../components/ShowNotification/index'
import { useGetDownloadPdf, useResendPaymentLink, useUpdateCustomerEmail, useGetDownloadDraftPdf } from '../../../Policy/state/hooks/usePolicyState'
import ProductBottomSheet from '../../../../../components/ProductBottomSheet/index'
import { useErrorContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { downloadFile } from '../../../../../methods/file'
import ChangeCustomerEmail from '../ChangeCustomerEmail'

function QuoteActions ({
  quote = {}, isPaymentSuccess, isDraft,
  isPayLater, email, onUpdateEmailChange = () => {}
}) {
  const history = useHistory()
  const [showProducts, setShowProductModal] = useState()
  const [showChangeEmail, setShowChangeEmail] = useState(false)
  const [{ getDownloadPdfData }, downloadPdfReq] = useGetDownloadPdf()
  const [{ getDownloadDraftPdfData }, downloadDraftPdfReq] = useGetDownloadDraftPdf()
  const [{ getDownloadPdfStatus, resendPaymentLinkStatus, updateEmailStatus, getDownloadDraftPdfStatus }] = useErrorContextValue()
  const [, resendPaymentLinkReq] = useResendPaymentLink()
  const [, updateCustomerEmailReq] = useUpdateCustomerEmail()
  const { resetError } = useResetError()

  useEffect(() => {
    if (getDownloadPdfStatus === 'success' && getDownloadPdfData) {
      downloadFile(getDownloadPdfData.pdf_url)
      resetError(['getDownloadPdfStatus'])
    } else if (getDownloadPdfStatus === 'success') {
      ShowSnackbar.error({
        visible: true,
        text: getDownloadPdfStatus
      })
      resetError(['getDownloadPdfStatus'])
    }

    if (getDownloadDraftPdfStatus === 'success' && getDownloadDraftPdfData) {
      downloadFile(getDownloadDraftPdfData.pdf_url)
      resetError(['getDownloadDraftPdfStatus'])
    } else if (getDownloadDraftPdfStatus === 'success') {
      ShowSnackbar.error({
        visible: true,
        text: getDownloadDraftPdfStatus
      })
      resetError(['getDownloadDraftPdfStatus'])
    }

    if (resendPaymentLinkStatus === 'success') {
      ShowSnackbar.success({
        visible: true,
        text: LANG_STRINGS.linkSendSuccessfully
      })
      resetError(['resendPaymentLinkStatus'])
    }

    if (updateEmailStatus === 'success') {
      ShowSnackbar.success({
        visible: true,
        text: LANG_STRINGS.changeEmailSuccessful
      })
      onUpdateEmailChange()
      setShowChangeEmail(false)
      resetError(['updateEmailStatus'])
    }
  }, [
    getDownloadPdfStatus, resetError, getDownloadPdfData,
    getDownloadDraftPdfData, getDownloadDraftPdfStatus,
    resendPaymentLinkStatus, updateEmailStatus, onUpdateEmailChange
  ])

  const policyDetails = useMemo(() => {
    const { pkgDetail = {} } = getFromLocalStorageData(SEND_QUOTATION_SUCCESS)
    if (!Object.keys(pkgDetail).length) {
      return {
        ...quote.product,
        ...quote.policy_detail,
        ...quote
      }
    }
  }, [quote])

  const quoteActions = useMemo(() => {
    const productCode = policyDetails?.package?.product?.code
    if (isPaymentSuccess) {
      if (productCode === CAR_PROTECTION) {
        return CUSTOMER_PAYMENT_SUCCESS_ACTIONS
      }
      const actionItems = [...CUSTOMER_PAYMENT_SUCCESS_ACTIONS]
      actionItems.splice(CUSTOMER_PAYMENT_SUCCESS_ACTIONS.length - 1, 1)
      return actionItems
    }
    if (productCode === CAR_PROTECTION) {
      if (isPayLater) {
        return [...QUOTE_SUCCESS_ACTIONS].splice(3)
      }
      return [...QUOTE_SUCCESS_ACTIONS]
    }
    const actions = [...QUOTE_SUCCESS_ACTIONS]
    actions.splice(4, 1)
    return actions
  }, [isPaymentSuccess, isPayLater, policyDetails])

  const getSharingData = useCallback((source) => {
    let totalBill = policyDetails.accessories_sum_insured + policyDetails.vehicle_sum_insured
    let periodType = LANG_STRINGS.months
    let period = policyDetails?.premium?.period
    if (policyDetails.package_type === PROPERTY_PROTECTION_BASIC) {
      totalBill = policyDetails.total_sum_insured
    }
    if (policyDetails?.productCode === HEALTH_FULL_PROTECTION) {
      totalBill = policyDetails.total_sum_insured
    }
    if (policyDetails?.package?.code === MARINE_CARGO_PROTECTION) {
      totalBill = policyDetails.total_sum_insured
      period = 30
      periodType = LANG_STRINGS.days
    }
    let linkOfShare = `${APP_HOST}/customer/policy/${policyDetails.id}/?source=${source}`
    if (isDraft) {
      linkOfShare = `${APP_HOST}/customer/draft/policy/${policyDetails.id}/?source=${source}`
    }
    let extraData = `Rincian transaksi\nNama Produk: ${policyDetails.product.name || policyDetails.package.product.name}\n`
    extraData += `Penyedia Asuransi: ${policyDetails.provider.name}\n`
    extraData += `Periode Perlindungan: ${period} ${periodType}\n`
    if (policyDetails?.discount) {
      extraData += `Diskon: ${formatMoney(policyDetails.discount, 0)}\n`
    }
    extraData += `Premi: ${formatMoney(policyDetails.sub_total, 0)}\n`
    extraData += `Jumlah Pertanggungan: ${formatMoney(totalBill, 0)}`

    return {
      data: `${LANG_STRINGS.quotationShareMsg.replace('XXX', linkOfShare)}\n\n${extraData}`,
      link: linkOfShare
    }
  }, [policyDetails, isDraft])

  const handleActionClick = useCallback(({ type }) => {
    switch (type) {
      case 'downloadPdf':
        isDraft ? (
          downloadDraftPdfReq({
            draftId: policyDetails.id
          })
        )
          : (
            downloadPdfReq({
              policyId: quote.id
            })
          )
        break
      case 'whatsApp': {
        const shareData = getSharingData('quotation_wa')
        const queryString = queryBuilder({
          text: shareData.data
        })
        gTagOnSendSendQuotationWA()
        if (ANDROID_BRIDGE.shareOnWhatsapp) {
          ANDROID_BRIDGE.shareOnWhatsapp(
            '',
            shareData.data
          )
          return
        }
        const url = encodeURI(`${WHATS_APP_URL}${queryString}`)
        window.open(url, '_blank')
        break
      }
      case 'copyLink': {
        const sharingDate = getSharingData('quotation_copy')
        copySharingData(sharingDate.link)
        ShowSnackbar.success({
          visible: true,
          text: 'Menyalin ke clipboard berhasil'
        })
        break
      }
      case 'resendLinkToEmail':
        return resendPaymentLinkReq({ policyId: quote.id })
      case 'changeEmailAddress':
        return setShowChangeEmail(true)
      case 'backToHome':
        history.replace('/dashboard')
        break
      case 'makeCarProtectionAgain':
        history.replace('/motor_vehicle/v2')
        break
      default:
        return setShowProductModal(true)
    }
  }, [
    history, getSharingData, quote, downloadPdfReq, downloadDraftPdfReq,
    resendPaymentLinkReq, policyDetails?.id, isDraft
  ])

  const handleChangeEmail = useCallback((email) => {
    updateCustomerEmailReq({
      body: {
        email
      },
      policyId: quote.id
    })
  }, [updateCustomerEmailReq, quote])

  return (
    <QuoteActionsStyle>
      <Heading
        title={LANG_STRINGS.moreOptions}
      />
      <div className='quote-actions'>
        {
          quoteActions.map(item => (
            <div
              key={item.type}
              onClick={() => handleActionClick(item)}
              className='action'
              data-gtm-element-id='quote-actions'
              data-gtm-entry={item.id}
            >
              <img
                src={item.icon}
                width='24px'
                alt={item.name}
                data-gtm-element-id='quote-actions'
                data-gtm-entry={item.id}
              />
              <div
                className='action-name'
                data-gtm-element-id='quote-actions'
                data-gtm-entry={item.id}
              >
                {item.name}
              </div>
            </div>
          ))
        }
      </div>
      {
        showProducts && (
          <ProductBottomSheet
            show={showProducts}
            onClose={() => setShowProductModal(false)}
          />
        )
      }
      <ChangeCustomerEmail
        show={showChangeEmail}
        onClose={() => setShowChangeEmail(false)}
        onChangeEmail={handleChangeEmail}
        oldEmail={email}
      />
      <ShowSnackbar />
    </QuoteActionsStyle>
  )
}

export default QuoteActions
